/* machine-generated by m2c: a starting point, not a match */
#ifndef M2C_DEFINES
#define M2C_DEFINES
typedef s32 M2C_UNK;
typedef s8 M2C_UNK8;
typedef s16 M2C_UNK16;
typedef s32 M2C_UNK32;
#define M2C_FIELD(expr, type_ptr, offset) (*(type_ptr)((s8 *)(expr) + (offset)))
#define M2C_BITWISE(type, expr) ((type)(expr))
#define M2C_ERROR(desc) (0)
#define M2C_CARRY 0
#define M2C_OVERFLOW(a) (0)
#endif

s32 loadSaveSlot(s32);                             /* extern */
M2C_UNK deserializeSaveData();                            /* extern */

/* Loads the given save slot; if the load returns 1, runs the follow-up refresh. Returns the load result. */ s32 loadSaveSlotAndRefresh(s32 slot) {
    s32 result;

    result = loadSaveSlot(slot & 0xFFFF) & 0xFFFF;
    if (result == 1) {
        deserializeSaveData();
    }
    return result;
}
